    Bug 2028028 - Fix intermittent comm/calendar/test/browser/browser_taskDisplay.js | Correct number of tasks. r=tobyp


    A superseded refresh job now returns early so the test's `await treeRefresh()` resolves on the correct job's event.

    Differential Revision: https://phabricator.services.mozilla.com/D307341

diff --git a/calendar/base/content/calendar-task-tree.js b/calendar/base/content/calendar-task-tree.js
index 7ecb98a902b..4b96d1ecb8f 100644
--- a/calendar/base/content/calendar-task-tree.js
+++ b/calendar/base/content/calendar-task-tree.js
@@ -520,8 +520,10 @@
         calendar: null,
         items: null,
         operation: null,
+        cancelled: false,

         async cancel() {
+          this.cancelled = true;
           if (this.operation) {
             await this.operation.cancel();
             this.operation = null;
@@ -542,14 +544,18 @@
             this.items = this.items.concat(items);
           }

+          if (this.cancelled || this.tree.mPendingRefreshJobs[calendar.id] != this) {
+            // A newer refresh job for this calendar has superseded us (or we were
+            // cancelled). Don't mutate the view or fire "refresh" with stale data.
+            return;
+          }
+
           if (!this.tree.mTreeView.tree) {
             // Looks like we've been disconnected from the DOM, there's no point in continuing.
             return;
           }

-          if (calendar.id in this.tree.mPendingRefreshJobs) {
-            delete this.tree.mPendingRefreshJobs[calendar.id];
-          }
+          delete this.tree.mPendingRefreshJobs[calendar.id];

           const oldItems = this.tree.mTaskArray.filter(item => item.calendar.id == calendar.id);
           this.tree.mTreeView.modifyItems(this.items, oldItems);
diff --git a/calendar/base/content/widgets/calendar-filter.js b/calendar/base/content/widgets/calendar-filter.js
index 4e660f4e6ee..8db17e6ca91 100644
--- a/calendar/base/content/widgets/calendar-filter.js
+++ b/calendar/base/content/widgets/calendar-filter.js
@@ -1313,6 +1313,11 @@ let CalendarFilteredViewMixin = Base =>
       const iterator = cal.iterate.streamValues(this.#filter.getItems(calendar));
       this.#iterators.add(iterator);
       const items = await Array.fromAsync(iterator);
+      if (!this.#iterators.has(iterator)) {
+        // #invalidate() cancelled this refresh while we were awaiting results.
+        // Don't add stale items to the (now cleared) view of a newer refresh.
+        return;
+      }
       this.addItems(items.flat());
       this.#iterators.delete(iterator);
     }
